from .target import validate


KNOWN = {'queued': 'pending', 'sent': 'fulfilled', 'failed': 'failed'}


def migrate_all(rows):
    result = []
    for row in rows:
        status = KNOWN.get(row['status'])
        if status is None:
            raise ValueError('legacy status mapping needed: ' + row['status'])
        result.append(validate({'id': row['id'], 'status': status,
                                'total_cents': row['total_cents']}))
    return result

